#!/usr/bin/env python3
"""Test vectors for apple/cloudkit, generated by running the REAL FindMy.py (the oracle) on fixed synthetic inputs.

    python app/tools/oracle/cloudkit_vectors.py

Writes android/app/src/test/resources/fixtures/cloudkit/{der,pcs,servicekeys,records,beacons,client}.json.

Every key, record and zone here is synthetic and derived from fixed seeds; no real account, key or token is involved. The
inputs are built the way the fork's own offline tests build them (tests/test_pcs.py `build_protection`/`build_meta`,
tests/fake_account.py), with every random choice fixed: ephemeral ECDH keys come from seeds, GCM nonces are fixed, ECDSA is
deterministic (RFC 6979). Run it twice, get the same files.

The library's own functions produce or consume every value written here: this script only builds inputs and records what
the library returns (or which exception class it raised).
"""

from __future__ import annotations

import asyncio
import gzip
import hashlib
import hmac
import json
import os
import struct
from datetime import datetime, timedelta, timezone
from pathlib import Path

os.environ["TZ"] = "UTC"

from cryptography.hazmat.primitives import hashes  # noqa: E402
from cryptography.hazmat.primitives.asymmetric import ec  # noqa: E402
from cryptography.hazmat.primitives.keywrap import aes_key_wrap  # noqa: E402
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat  # noqa: E402

import findmy.cloudkit.beacons as beacons  # noqa: E402
import findmy.cloudkit.client as client_mod  # noqa: E402
from findmy.cloudkit import der, pcs, records  # noqa: E402
from findmy.cloudkit.constants import BEACON_STORE_ZONE  # noqa: E402
from findmy.cloudkit.proto import cloudkit_pb2 as ck  # noqa: E402
from findmy.cloudkit.proto import cuttlefish_pb2 as cf  # noqa: E402
from findmy.keychain import servicekey  # noqa: E402

OUT = Path(__file__).resolve().parents[2] / "android/app/src/test/resources/fixtures/cloudkit"
P256_N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
P384_N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFC7634D81F4372DDF581A0DB248B0A77AECEC196ACCC52973
APPLE_EPOCH = datetime(2001, 1, 1, tzinfo=timezone.utc)


def seed(label: str, n: int = 32) -> bytes:
    out = b""
    counter = 0
    while len(out) < n:
        out += hashlib.sha256(f"osfind-cloudkit-oracle:{label}:{counter}".encode()).digest()
        counter += 1
    return out[:n]


def p256(label: str) -> ec.EllipticCurvePrivateKey:
    return ec.derive_private_key(int.from_bytes(seed(label), "big") % (P256_N - 1) + 1, ec.SECP256R1())


def p384(label: str) -> ec.EllipticCurvePrivateKey:
    return ec.derive_private_key(int.from_bytes(seed(label, 48), "big") % (P384_N - 1) + 1, ec.SECP384R1())


def scalar(key: ec.EllipticCurvePrivateKey) -> str:
    size = (key.curve.key_size + 7) // 8
    return key.private_numbers().private_value.to_bytes(size, "big").hex()


def key_json(key: ec.EllipticCurvePrivateKey) -> dict:
    return {"curve": key.curve.name, "d": scalar(key)}


def uncompressed(key: ec.EllipticCurvePrivateKey) -> bytes:
    return key.public_key().public_bytes(Encoding.X962, PublicFormat.UncompressedPoint)


def compressed(key: ec.EllipticCurvePrivateKey) -> bytes:
    return key.public_key().public_bytes(Encoding.X962, PublicFormat.CompressedPoint)


def bare_x(key: ec.EllipticCurvePrivateKey) -> bytes:
    size = (key.curve.key_size + 7) // 8
    return uncompressed(key)[1 : 1 + size]


def dump(name: str, data) -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / name).write_text(json.dumps(data, indent=1, sort_keys=True) + "\n")


def error_name(fn) -> str | None:
    """Run fn and name the library exception it raised (None when it returned)."""
    try:
        fn()
    except Exception as e:  # noqa: BLE001
        return type(e).__name__
    return None


# ------------------------------------------------------------------------------------------------- DER builders
# The same shapes the fork's tests/test_pcs.py writes (der_tlv & co.), so a wrong parse is visible.


def tlv(tag: int, content: bytes) -> bytes:
    if len(content) < 0x80:
        return bytes([tag, len(content)]) + content
    length = len(content).to_bytes((len(content).bit_length() + 7) // 8, "big")
    return bytes([tag, 0x80 | len(length)]) + length + content


def seq(*e: bytes) -> bytes:
    return tlv(0x30, b"".join(e))


def set_(*e: bytes) -> bytes:
    return tlv(0x31, b"".join(e))


def int_(v: int) -> bytes:
    if v == 0:
        return tlv(0x02, b"\x00")
    return tlv(0x02, v.to_bytes((v.bit_length() + 8) // 8, "big", signed=v < 0))


def octet(c: bytes) -> bytes:
    return tlv(0x04, c)


def ctx(n: int, c: bytes) -> bytes:
    return tlv(0xA0 | n, c)


def app(n: int, c: bytes) -> bytes:
    return tlv(0x60 | n, c)


def utf8(s: str) -> bytes:
    return tlv(0x0C, s.encode())


# ------------------------------------------------------------------------------------------------- PCS builders


def wrap_master_key(recipient: ec.EllipticCurvePublicKey, master_key: bytes, eph_label: str, *, corrupt_checksum: bool = False) -> bytes:
    """RFC 6637 as PCS uses it (the fork's test wrap_master_key), with a seeded ephemeral key."""
    ephemeral = p256("ephemeral:" + eph_label)
    shared = ephemeral.exchange(ec.ECDH(), recipient)
    kek = hashlib.sha256(struct.pack(">I", 1) + shared + pcs._RFC6637_PARAM).digest()  # noqa: SLF001
    checksum = (sum(master_key) + (1 if corrupt_checksum else 0)) % 65536
    framed = bytes([1]) + master_key + checksum.to_bytes(2, "big")
    pad = -len(framed) % 8 or 8
    framed += bytes([pad]) * pad
    wrapped = aes_key_wrap(kek[:16], framed)
    x = ephemeral.public_key().public_numbers().x.to_bytes(32, "big")
    return (256).to_bytes(2, "big") + x + bytes([len(wrapped)]) + wrapped


def object_signature(*, roll_count=1, outer=2, pk_type=3, public_key=b"\x02" + b"\x11" * 32, signature=b"sig", key_id=b"",
                     symm_key_count=None, attributes=None, ec_key_list=None, signature2=None) -> bytes:
    parts = [int_(roll_count), int_(outer), seq(int_(pk_type), octet(public_key)), seq(octet(key_id), int_(1), octet(signature))]
    if symm_key_count is not None:
        parts.append(ctx(0, int_(symm_key_count)))
    if signature2 is not None:
        parts.append(ctx(1, seq(octet(b""), int_(1), octet(signature2))))
    if ec_key_list is not None:
        parts.append(ctx(2, ec_key_list))
    if attributes is not None:
        parts.append(ctx(3, attributes))
    return seq(*parts)


def build_protection(*, entries, truncated_key_id: bytes | None, version: int = 5, hmac_master_key: bytes | None = None,
                     meta: bytes = b"meta", signature_data: bytes | None = None, attributes: list[bytes] | None = None,
                     signature: bytes | None = None, hmac_override: bytes | None = None) -> bytes:
    share_keys = []
    for public_key, ciphertext, flags in entries:
        parts = [seq(int_(1), octet(public_key)), octet(ciphertext)]
        if flags is not None:
            parts.append(int_(flags))
        share_keys.append(seq(*parts))
    keyset = seq(int_(0), set_(*share_keys))
    obj = signature_data if signature_data is not None else octet(b"sigdata")
    sig_data = seq(int_(version), octet(obj))
    if hmac_override is not None:
        mac = hmac_override
    elif hmac_master_key is None:
        mac = b"\xaa" * 32
    else:
        mac = hmac.new(pcs.derive_hmac_key(hmac_master_key), keyset + meta + obj, hashlib.sha256).digest()
    members = [keyset, ctx(0, octet(meta)), ctx(1, sig_data), octet(mac)]
    if truncated_key_id is not None:
        members.append(ctx(2, octet(truncated_key_id)))
    if signature is not None:
        members.append(ctx(3, signature))
    if attributes is not None:
        members.append(ctx(4, seq(*attributes)))
    return app(1, seq(*members))


def signed_protection(master_key: bytes, entries, *, version: int, meta: bytes, past: bool = False, wrong_signer: bool = False,
                      symm_key_count=None, attributes=None, ec_key_list=None) -> bytes:
    """A structure whose ObjectSignature verifies under the master EC key (two passes, as the fork's signed_protection)."""
    signer = ec.derive_private_key(pcs.derive_master_ec_private_key(master_key), ec.SECP256R1())
    key_id = compressed(p256("someone-else")) if wrong_signer else compressed(signer)
    extra = {"symm_key_count": symm_key_count, "attributes": attributes, "ec_key_list": ec_key_list}

    def build(obj: bytes) -> bytes:
        return build_protection(entries=entries, truncated_key_id=pcs.compute_key_id(master_key)[:4], version=version,
                                hmac_master_key=master_key, meta=meta, signature_data=obj)

    draft = pcs.ShareProtection.from_der(build(object_signature(key_id=key_id, **extra)))
    placeholder = pcs.ObjectSignature.from_der(object_signature(key_id=key_id, **extra))
    signed = pcs.build_signed_data(draft, placeholder)
    real = signer.sign(signed, ec.ECDSA(hashes.SHA256(), deterministic_signing=True))
    if past:
        return build(object_signature(key_id=b"", signature=b"stale", signature2=real, **extra))
    return build(object_signature(key_id=key_id, signature=real, **extra))


def holder(master_key: bytes) -> pcs.UnwrappedProtection:
    return pcs.UnwrappedProtection(master_key=master_key, share_key_derived=False, read_only=False, hmac_verified=False,
                                   signature_verified=None)


def pcs_key_message(enc: bytes, sig: bytes | None = None) -> bytes:
    keys = cf.PcsServiceKeys(encryption_key=cf.PcsPrivateKey(key=enc))
    if sig is not None:
        keys.signing_key.key = sig
    return keys.SerializeToString()


def v2_payload(message: bytes, *, explicit: bool) -> bytes:
    if explicit:
        return app(5, seq(octet(message)))
    return app(5, octet(message))


def blob64(key: ec.EllipticCurvePrivateKey) -> bytes:
    return bare_x(key) + bytes.fromhex(scalar(key))


def identity_observed(key: ec.EllipticCurvePrivateKey, name: str = "PCS") -> bytes:
    """[observed] (fork tests/test_pcs.py): identity = { INT, OCTET(APP 2 { name, SET { SEQ { blob64 } }, SET {}, hash }) }."""
    members = utf8(name) + set_(seq(octet(blob64(key)))) + set_()
    without = app(2, seq(members))
    digest = hashlib.sha256(without).digest()
    keyset = app(2, seq(members + octet(digest)))
    return seq(int_(1), octet(keyset))


def identity_v2(key: ec.EllipticCurvePrivateKey) -> bytes:
    """The fork's build_meta identity: { INT, OCTET(SEQ { 'k', SET { APP 5 { OCTET pcs } }, SET {}, zeros32 }) }."""
    v_data = app(5, octet(pcs_key_message(bytes.fromhex(scalar(key)))))
    nested = seq(utf8("k") + set_(v_data) + set_() + octet(bytes(32)))
    return seq(int_(1), octet(nested))


def meta_plaintext(*, symm_keys=None, identities=None, wrap_app: bool = False) -> bytes:
    members = b""
    if symm_keys:
        members += ctx(0, set_(*[octet(k) for k in symm_keys]))
    members += ctx(1, octet(b"not understood"))
    if identities:
        members += ctx(2, set_(*identities))
    plain = seq(members)
    return app(3, plain) if wrap_app else plain


def encrypt_meta(master_key: bytes, plaintext: bytes, iv_label: str) -> bytes:
    return pcs.encrypt_field(plaintext, holder(master_key), pcs.FieldContext.none(), iv=seed("iv:" + iv_label, 12))


def unwrapped_json(u: pcs.UnwrappedProtection) -> dict:
    return {
        "master_key": u.master_key.hex(),
        "share_key_derived": u.share_key_derived,
        "read_only": u.read_only,
        "hmac_verified": u.hmac_verified,
        "signature_verified": u.signature_verified,
        "symmetric_keys": [k.hex() for k in u.meta.symmetric_keys],
        "private_keys": [key_json(k) for k in u.meta.private_keys],
    }


# ------------------------------------------------------------------------------------------------- der.json


def element_json(e: der.DerElement) -> dict:
    return {"cls": e.tag_class, "constructed": e.constructed, "tag": e.tag_number, "content": e.content.hex(), "raw": e.raw.hex()}


def gen_der() -> None:
    samples = {
        "ints": seq(int_(0), int_(1), int_(127), int_(128), int_(-1), int_(-129), int_(2**70)),
        "long_length": octet(bytes(range(256)) * 2),
        "nested_context": app(1, seq(ctx(0, octet(b"meta")), octet(b"mac"), ctx(2, octet(b"\x01\x02\x03\x04")))),
        "high_tag": bytes([0x9F, 0x81, 0x00, 0x02]) + b"hi" + octet(b"x"),
        "empty_int": bytes([0x02, 0x00]),
        "utf8": utf8("BeaconStore"),
        "set_of_two": set_(octet(b"b"), octet(b"a")),
    }
    parsed = {}
    for name, data in samples.items():
        elements = der.parse_all(data)
        entry = {"data": data.hex(), "elements": [element_json(e) for e in elements]}
        entry["children"] = [[element_json(c) for c in e.children()] if e.constructed else None for e in elements]
        entry["ints"] = [e.as_int() for e in elements if e.is_universal(der.TAG_INTEGER)]
        if elements[0].constructed:
            sub = elements[0].children()
            entry["sub_ints"] = [c.as_int() for c in sub if c.is_universal(der.TAG_INTEGER)]
            entry["rebuild_without"] = [der.rebuild_without(elements[0], i).hex() for i in range(len(sub))]
        parsed[name] = entry

    errors = {
        "truncated_tag": b"",
        "no_length": b"\x04",
        "indefinite": b"\x30\x80\x00\x00",
        "length_past_end": b"\x04\x05abc",
        "long_length_past_end": b"\x04\x82\x01",
        "unterminated_high_tag": b"\x9f\x81",
        "children_of_primitive": octet(b"abc"),
        "unwrap_two": ctx(0, octet(b"a") + octet(b"b")),
        "expect_app_wrong": seq(octet(b"a")),
    }
    errs = {}
    for name, data in errors.items():
        def run(d=data, n=name):
            if n == "children_of_primitive":
                der.parse_one(d)[0].children()
            elif n == "unwrap_two":
                der.parse_one(d)[0].unwrap()
            elif n == "expect_app_wrong":
                der.expect_application(d, 1)
            else:
                der.parse_all(d)
        errs[name] = {"data": data.hex(), "error": error_name(run)}

    dump("der.json", {"parsed": parsed, "errors": errs, "encode_length": {str(n): der.encode_length(n).hex() for n in (0, 5, 127, 128, 255, 256, 65535, 65536)}})


# ------------------------------------------------------------------------------------------------- pcs.json


def gen_pcs() -> dict:
    out: dict = {}

    # --- §5 key derivation
    masters = [bytes(range(16)), seed("mk-a", 16), seed("mk-b", 32), seed("mk-c", 7), b""]
    labels = [pcs.LABEL_SHARE_KEY, pcs.LABEL_HMAC_KEY, pcs.LABEL_KEY_ID, pcs.LABEL_ENCRYPTION_KEY, pcs.KEY_ID_INPUT]
    out["kdf"] = []
    for mk in masters:
        entry = {"master": mk.hex(), "derive": {}, "derive48": {}}
        for label in labels:
            entry["derive"][label.decode()] = pcs.derive_key(mk, label).hex()
            entry["derive48"][label.decode()] = pcs.derive_key(mk, label, length=48).hex()
        entry["key_id"] = pcs.compute_key_id(mk).hex()
        entry["encryption_key"] = pcs.derive_encryption_key(mk).hex()
        entry["hmac_key"] = pcs.derive_hmac_key(mk).hex()
        try:
            entry["master_ec"] = format(pcs.derive_master_ec_private_key(mk), "064x")
        except pcs.PCSError:
            entry["master_ec"] = None
        out["kdf"].append(entry)

    # --- §6 field encryption: what encrypt_field writes, and what decrypt_field makes of variations
    fields = []
    for i, (mk, plain, context, split) in enumerate([
        (bytes(range(16)), b"hello field", pcs.FieldContext("BeaconStore", "REC-1", "name"), (2, 2)),
        (seed("mk-a", 16), b"", pcs.FieldContext("BeaconStore", "REC-2", "privateKey"), (2, 2)),
        (seed("mk-b", 32), bytes(range(200)), pcs.FieldContext("Zone", "Rec", "f"), (2, 5)),
        (seed("mk-a", 16), b"meta-like", pcs.FieldContext.none(), (2, 0)),
    ]):
        iv = seed(f"field-iv-{i}", 12)
        data = pcs.encrypt_field(plain, holder(mk), context, key_id_split=split, iv=iv)
        parsed = pcs.parse_encrypted_field(data)
        fields.append({
            "master": mk.hex(), "plaintext": plain.hex(), "zone": context.zone_name, "record": context.record_name,
            "field": context.field_name, "aad_context": context.as_bytes().hex(), "iv": iv.hex(), "split": list(split),
            "ciphertext": data.hex(), "header": parsed.header.hex(), "key_id": parsed.key_id.hex(), "tag": parsed.tag.hex(),
            "body": parsed.ciphertext.hex(), "decrypted": pcs.decrypt_field(data, holder(mk), context).hex(),
        })
    out["fields"] = fields

    base = fields[0]
    data = bytes.fromhex(base["ciphertext"])
    mk = bytes.fromhex(base["master"])
    good = pcs.FieldContext("BeaconStore", "REC-1", "name")
    tampered = bytearray(data)
    tampered[-1] ^= 1
    bad_cases = {
        "wrong_record": (data, mk, pcs.FieldContext("BeaconStore", "REC-2", "name"), True),
        "wrong_zone": (data, mk, pcs.FieldContext("Other", "REC-1", "name"), True),
        "empty_context": (data, mk, pcs.FieldContext.none(), True),
        "tampered": (bytes(tampered), mk, good, True),
        "version_4": (b"\x04" + data[1:], mk, good, True),
        "too_short": (data[:3], mk, good, True),
        "truncated": (data[:6 + 12 + 11], mk, good, True),
        "wrong_key_checked": (data, seed("other", 16), good, True),
        "wrong_key_unchecked": (data, seed("other", 16), good, False),
        "no_key_id_check_right_key": (data, mk, good, False),
    }
    out["field_failures"] = {}
    for name, (d, key, context, check) in bad_cases.items():
        result: dict = {"data": d.hex(), "master": key.hex(), "zone": context.zone_name, "record": context.record_name,
                        "field": context.field_name, "check_key_id": check}
        try:
            result["plaintext"] = pcs.decrypt_field(d, holder(key), context, check_key_id=check).hex()
            result["error"] = None
        except Exception as e:  # noqa: BLE001
            result["error"] = type(e).__name__
        out["field_failures"][name] = result

    # --- RFC 6637 unwrap
    recipient = p256("recipient")
    other = p256("not-the-recipient")
    unwraps = []
    for name, mk, corrupt, key in [("ok16", seed("wrapped-16", 16), False, recipient), ("ok32", seed("wrapped-32", 32), False, recipient),
                                   ("bad_checksum", seed("wrapped-16", 16), True, recipient), ("wrong_key", seed("wrapped-16", 16), False, other)]:
        ct = wrap_master_key(recipient.public_key(), mk, name, corrupt_checksum=corrupt)
        entry = {"name": name, "key": key_json(key), "ciphertext": ct.hex()}
        try:
            entry["master"] = pcs.unwrap_share_key(key, ct).hex()
            entry["error"] = None
        except Exception as e:  # noqa: BLE001
            entry["error"] = type(e).__name__
        unwraps.append(entry)
    ct = wrap_master_key(recipient.public_key(), seed("wrapped-16", 16), "ok16")
    for name, bad in [("too_short", ct[:2]), ("point_overrun", ct[:30]), ("wrapped_short", ct[:-3]), ("x_not_on_curve", ct[:2] + bytes(31) + b"\x05" + ct[34:])]:
        entry = {"name": name, "key": key_json(recipient), "ciphertext": bad.hex()}
        try:
            entry["master"] = pcs.unwrap_share_key(recipient, bad).hex()
            entry["error"] = None
        except Exception as e:  # noqa: BLE001
            entry["error"] = type(e).__name__
        unwraps.append(entry)
    out["unwrap_share_key"] = unwraps

    # --- public key forms (matching a keyset entry against a held key)
    out["public_forms"] = []
    for k in (p256("forms-a"), p256("forms-b"), p384("forms-c")):
        forms = sorted(f.hex() for f in pcs.public_key_forms(k.public_key()))
        out["public_forms"].append({"key": key_json(k), "forms": forms, "compressed": pcs.compress_public_key(k.public_key()).hex(),
                                    "bare_x": pcs.bare_x(k.public_key()).hex()})

    # --- ShareProtection parsing, ObjectSignature, signed data
    mk = seed("protection-mk", 16)
    obj = object_signature(roll_count=9, outer=4, pk_type=5, symm_key_count=7, attributes=seq(int_(1)), ec_key_list=seq(octet(b"ec")),
                           signature2=b"past")
    prot = build_protection(entries=[(b"\x02" + b"\x22" * 32, b"ct-1", None), (b"\x33" * 32, b"ct-2", 1), (b"\x44" * 64, b"ct-3", 6)],
                            truncated_key_id=b"\x01\x02\x03\x04", version=3, hmac_master_key=mk, meta=b"the-meta", signature_data=obj,
                            attributes=[seq(int_(7), octet(b"attr-7"))], signature=seq(octet(b"kid"), int_(1), octet(b"outer-sig")))
    sp = pcs.ShareProtection.from_der(prot)
    os_ = pcs.ObjectSignature.from_der(sp.signature_data.data)
    out["protection_parse"] = {
        "der": prot.hex(), "master": mk.hex(),
        "keys": [{"key_type": k.key_type, "public_key": k.public_key.hex(), "ciphertext": k.ciphertext.hex(), "flags": k.flags,
                  "read_only": k.read_only} for k in sp.keys],
        "meta": sp.meta.hex(), "version": sp.signature_data.version, "signature_data": sp.signature_data.data.hex(),
        "hmac": sp.hmac.hex(), "truncated_key_id": sp.truncated_key_id.hex(),
        "signature": {"key_id": sp.signature.key_id.hex(), "digest": sp.signature.digest, "signature": sp.signature.signature.hex()},
        "attributes": [{"key": a.key, "value": a.value.hex()} for a in sp.attributes],
        "keyset_der": sp.keyset_der.hex(), "signature_data_der": sp.signature_data_der.hex(),
        "hmac_verified": pcs.verify_protection_hmac(sp, mk), "hmac_verified_wrong_key": pcs.verify_protection_hmac(sp, seed("x", 16)),
        "object_signature": {"roll_count": os_.roll_count, "outer": os_.outer_sign_key_type, "pk_type": os_.public.key_type,
                             "pk": os_.public.public_key.hex(), "symm_key_count": os_.symm_key_count,
                             "signature2": os_.signature2.signature.hex() if os_.signature2 else None,
                             "ec_key_list_der": os_.ec_key_list_der.hex(), "attributes_der": os_.attributes_der.hex()},
        "signed_data": pcs.build_signed_data(sp, os_).hex(),
        "signed_data_minimal": pcs.build_signed_data(sp, pcs.ObjectSignature.from_der(object_signature())).hex(),
    }
    out["protection_parse_errors"] = {
        name: {"der": d.hex(), "error": error_name(lambda d=d: pcs.ShareProtection.from_der(d))}
        for name, d in {
            "no_signature_data": app(1, seq(seq(int_(0), set_()), octet(b"mac"))),
            "wrong_app_tag": app(2, seq(seq(int_(0), set_()))),
            "share_key_one_member": app(1, seq(seq(int_(0), set_(seq(seq(int_(1), octet(b"pk"))))), ctx(1, seq(int_(5), octet(b"")))) ),
            "keyref_one_member": app(1, seq(seq(int_(0), set_(seq(seq(int_(1)), octet(b"ct")))), ctx(1, seq(int_(5), octet(b""))))),
            "not_der": b"\x61\x05\x30",
        }.items()
    }

    # --- signature check outcomes
    sigs = {}
    entries_none: list = []
    meta = b"sig-meta"
    for name, raw in {
        "verifies": signed_protection(mk, entries_none, version=5, meta=meta),
        "verifies_with_optionals": signed_protection(mk, entries_none, version=5, meta=meta, symm_key_count=3,
                                                     attributes=seq(int_(1)), ec_key_list=seq(octet(b"e"))),
        "past_signature": signed_protection(mk, entries_none, version=5, meta=meta, past=True),
        "wrong_signer": signed_protection(mk, entries_none, version=5, meta=meta, wrong_signer=True),
        "rejected": build_protection(entries=[], truncated_key_id=pcs.compute_key_id(mk)[:4], meta=meta,
                                     signature_data=object_signature(public_key=compressed(p256("x")), signature=b"\x30\x06\x02\x01\x01\x02\x01\x01")),
        "unparseable": build_protection(entries=[], truncated_key_id=b"", meta=meta, signature_data=octet(b"not a sequence")),
        "absent": build_protection(entries=[], truncated_key_id=b"", meta=meta, signature_data=b""),
    }.items():
        sp = pcs.ShareProtection.from_der(raw)
        sigs[name] = {"der": raw.hex(), "master": mk.hex(), "outcome": pcs.describe_protection_signature(sp, mk)}
    out["signatures"] = sigs
    out["signature_reasons"] = {"absent": pcs.SIGNATURE_ABSENT, "unparseable": pcs.SIGNATURE_UNPARSEABLE,
                                "wrong_signer": pcs.SIGNATURE_WRONG_SIGNER, "rejected": pcs.SIGNATURE_REJECTED}

    # --- unwrap_protection, every branch the read path reaches
    held_a = p256("held-a")
    held_b = p256("held-b")
    held_384 = p384("held-384")
    stranger = p256("stranger")
    unwraps = []
    id_key_1 = p256("identity-1")
    id_key_2 = p256("identity-2")
    id_key_3 = p384("identity-3")
    cases = []
    # (name, entries builder, version, signed, held keys, meta plaintext or None)
    for name, form, flags, version, signed, held, meta_spec in [
        ("compressed_v5_signed", "compressed", None, 5, True, [held_b, held_a], None),
        ("bare_x_v3_share_derived", "x", None, 3, False, [held_a], None),
        ("uncompressed_readonly_v3", "uncompressed", 1, 3, False, [held_a], None),
        ("xy_flags6_v1", "xy", 6, 1, True, [held_a, held_384], None),
        ("meta_symm_and_identities", "compressed", None, 5, True, [held_a],
         {"symm": [seed("symm-1", 16), seed("symm-2", 16)], "ids": [identity_observed(id_key_1), identity_v2(id_key_2)]}),
        ("meta_app_wrapped", "x", None, 5, False, [held_a], {"symm": [seed("symm-3", 16)], "ids": [identity_observed(id_key_3)], "app": True}),
        ("meta_garbage", "compressed", None, 5, False, [held_a], {"raw": b"\x04\x01"}),
        ("missing_key", "compressed", None, 5, False, [stranger, held_384], None),
        ("bad_key_id", "compressed", None, 5, False, [held_a], {"bad_kid": True}),
        ("no_key_id", "compressed", None, 5, False, [held_a], {"no_kid": True}),
    ]:
        master = seed("unwrap-mk:" + name, 16)
        effective = master if (version == 5 or (flags or 0) & 1) else master  # what is wrapped; derivation happens on read
        if meta_spec and "raw" in meta_spec:
            meta_bytes = encrypt_meta(master, meta_spec["raw"], name)
        elif meta_spec and ("symm" in meta_spec or "ids" in meta_spec):
            # the meta is encrypted under the key the reader ends up with (after any share-key derivation)
            final = master if (version == 5 or (flags or 0) & 1) else pcs.derive_key(master, pcs.LABEL_SHARE_KEY)
            meta_bytes = encrypt_meta(final, meta_plaintext(symm_keys=meta_spec.get("symm"), identities=meta_spec.get("ids"),
                                                            wrap_app=meta_spec.get("app", False)), name)
        else:
            meta_bytes = b"opaque-meta"
        public = {"compressed": compressed(held_a), "x": bare_x(held_a), "uncompressed": uncompressed(held_a),
                  "xy": uncompressed(held_a)[1:]}[form]
        entries = [
            (compressed(p256("decoy")), wrap_master_key(p256("decoy").public_key(), seed("decoy-mk", 16), name + ":decoy"), None),
            (public, wrap_master_key(held_a.public_key(), effective, name), flags),
        ]
        final = master if (version == 5 or (flags or 0) & 1) else pcs.derive_key(master, pcs.LABEL_SHARE_KEY)
        kid = pcs.compute_key_id(final)[:4]
        if meta_spec and meta_spec.get("bad_kid"):
            kid = b"\xde\xad\xbe\xef"
        if meta_spec and meta_spec.get("no_kid"):
            kid = None
        if signed:
            # signed under the final key's master EC key
            raw = signed_protection(final, entries, version=version, meta=meta_bytes)
        else:
            raw = build_protection(entries=entries, truncated_key_id=kid, version=version, hmac_master_key=final, meta=meta_bytes)
        cases.append((name, raw, held))
    for name, raw, held in cases:
        entry = {"name": name, "der": raw.hex(), "held": [key_json(k) for k in held]}
        try:
            entry["result"] = unwrapped_json(pcs.unwrap_protection(pcs.ShareProtection.from_der(raw), held))
            entry["error"] = None
        except Exception as e:  # noqa: BLE001
            entry["result"] = None
            entry["error"] = type(e).__name__
        unwraps.append(entry)
    out["unwrap_protection"] = unwraps

    # --- meta reading on its own (parse_meta over plaintexts, including the identity walk)
    metas = {}
    for name, plain in {
        "observed_identity": meta_plaintext(identities=[identity_observed(id_key_1)]),
        "v2_identity": meta_plaintext(identities=[identity_v2(id_key_2)]),
        "p384_identity": meta_plaintext(identities=[identity_observed(id_key_3)]),
        "two_keys_in_a_set": seq(ctx(2, set_(seq(int_(1), octet(app(2, seq(utf8("n") + set_(seq(octet(blob64(id_key_1))), seq(octet(blob64(id_key_2)))) + set_() + octet(bytes(range(32)))))))))),
        "halves_disagree": seq(ctx(2, set_(seq(int_(1), octet(seq(set_(seq(octet(bare_x(id_key_1) + bytes.fromhex(scalar(id_key_2)))), seq(octet(blob64(id_key_3)))))))))),
        "symm_only": meta_plaintext(symm_keys=[b"\x01" * 16, b"\x02" * 32]),
        "neither": seq(ctx(1, octet(b"x"))),
        "app_wrapped_two_children": app(4, seq(ctx(0, set_(octet(b"k" * 16)))) + octet(b"extra")),
        "v1_key": seq(ctx(2, set_(seq(octet(seq(octet(bytes.fromhex(scalar(id_key_2)))) ))))),
        "garbage_member": seq(ctx(2, set_(seq(octet(b"\x30\x05\x04\x03ab"), octet(b"\xff\xff"))))),
    }.items():
        try:
            m = pcs.parse_meta(plain)
            metas[name] = {"plaintext": plain.hex(), "symmetric_keys": [k.hex() for k in m.symmetric_keys],
                           "private_keys": [key_json(k) for k in m.private_keys], "error": None}
        except Exception as e:  # noqa: BLE001
            metas[name] = {"plaintext": plain.hex(), "error": type(e).__name__}
    out["parse_meta"] = metas

    # --- the zone level: unwrap_zone, unwrap_zone_record_defaults, select_default_master_key
    service = p256("service-key")
    zone_master = seed("zone-master", 16)
    zone_identity = p256("zone-identity")
    zone_meta = encrypt_meta(zone_master, meta_plaintext(symm_keys=[seed("zone-symm", 16)], identities=[identity_observed(zone_identity)]), "zone")
    zone_prot = build_protection(entries=[(bare_x(service), wrap_master_key(service.public_key(), zone_master, "zone"), None)],
                                 truncated_key_id=pcs.compute_key_id(zone_master)[:4], version=5, hmac_master_key=zone_master, meta=zone_meta)
    zone_keys = pcs.unwrap_zone(zone_prot, [service])
    bare_zone = build_protection(entries=[(compressed(service), wrap_master_key(service.public_key(), zone_master, "bare"), None)],
                                 truncated_key_id=pcs.compute_key_id(zone_master)[:4], version=5, meta=b"")
    defaults_master = [seed("default-1", 16), seed("default-2", 16)]
    defaults_meta = encrypt_meta(defaults_master[0], meta_plaintext(symm_keys=[defaults_master[1]]), "defaults")
    defaults_prot = build_protection(entries=[(compressed(zone_identity), wrap_master_key(zone_identity.public_key(), defaults_master[0], "defaults"), None)],
                                     truncated_key_id=pcs.compute_key_id(defaults_master[0])[:4], version=5, meta=defaults_meta)
    defaults = pcs.unwrap_zone_record_defaults(defaults_prot, zone_keys)
    out["zone"] = {
        "service_keys": [key_json(service)], "protection": zone_prot.hex(), "zone_keys": [key_json(k) for k in zone_keys],
        "bare_protection": bare_zone.hex(), "bare_zone_keys": [key_json(k) for k in pcs.unwrap_zone(bare_zone, [service])],
        "stranger_error": error_name(lambda: pcs.unwrap_zone(zone_prot, [stranger])),
        "record_defaults_protection": defaults_prot.hex(), "record_defaults": [k.hex() for k in defaults],
        "master_ec_inputs": [zone_master.hex(), seed("x", 16).hex()],
        "master_ec_keys": [key_json(k) for k in pcs.master_ec_keys([zone_master, seed("x", 16)])],
    }
    sel = []
    for keys, pcs_key in [(defaults, b""), (defaults[:1], b""), (defaults, pcs.compute_key_id(defaults[1])[:4]), (defaults, pcs.compute_key_id(defaults[0])[:2]),
                          (defaults, b"\x00\x00\x00\x00"), ([], b"")]:
        chosen = pcs.select_default_master_key(keys, pcs_key)
        sel.append({"keys": [k.hex() for k in keys], "pcs_key": pcs_key.hex(), "chosen": chosen.hex() if chosen is not None else None})
    out["select_default"] = sel
    out["_zone_objects"] = (service, zone_master, zone_identity, zone_prot, defaults_prot, zone_keys, defaults)
    return out


# ------------------------------------------------------------------------------------------------- servicekeys.json


def gen_servicekeys() -> None:
    k1, k2, k3 = p256("sk-1"), p256("sk-2"), p384("sk-3")
    payloads = {
        "v2_explicit_scalar": v2_payload(pcs_key_message(bytes.fromhex(scalar(k1))), explicit=True),
        "v2_implicit_scalar": v2_payload(pcs_key_message(bytes.fromhex(scalar(k1))), explicit=False),
        "v2_two_blobs_verified": v2_payload(pcs_key_message(blob64(k1), blob64(k2)), explicit=False),
        "v2_scalar_and_blob": v2_payload(pcs_key_message(bytes.fromhex(scalar(k1)), blob64(k2)), explicit=True),
        "v2_p384_blob": v2_payload(pcs_key_message(blob64(k3)), explicit=False),
        "v2_halves_disagree": v2_payload(pcs_key_message(bare_x(k1) + bytes.fromhex(scalar(k2))), explicit=False),
        "v2_unknown_field_numbers": v2_payload(bytes([0x2A, 64]) + blob64(k2) + bytes([0x32, 34, 0x0A, 32]) + bytes.fromhex(scalar(k1)), explicit=False),
        "v2_not_protobuf": v2_payload(b"\xff\xff\xff", explicit=False),
        "v2_empty": app(5, b""),
        "v2_no_octet": app(5, seq(int_(1))),
        "v1_scalar": seq(octet(bytes.fromhex(scalar(k2)))),
        "v1_blob_and_other": seq(octet(blob64(k1)), octet(b"\x01\x02"), octet(bytes.fromhex(scalar(k2)))),
        "v1_nothing_usable": seq(octet(b"short")),
        "v1_zero_scalar": seq(octet(bytes(32))),
        "primitive": octet(bytes(32)),
        "not_der": b"\x30\x81",
    }
    out = {}
    for name, data in payloads.items():
        try:
            keys = servicekey.service_keys_from_der(data)
            out[name] = {"data": data.hex(), "keys": [key_json(k) for k in keys.for_pcs()], "error": None}
        except Exception as e:  # noqa: BLE001
            out[name] = {"data": data.hex(), "keys": None, "error": type(e).__name__}
    dump("servicekeys.json", out)


# ------------------------------------------------------------------------------------------------- records + beacons


def ev(**kw) -> bytes:
    return ck.EncryptedValue(**kw).SerializeToString()


def make_record(name: str, record_type: str | None, fields: list, *, protection: bytes | None, pcs_key: bytes = b"", tag: str = "",
                zone_in_id: str | None = None) -> ck.Record:
    rec = ck.Record(etag=f"etag-{name}")
    rec.record_identifier.value.name = name
    rec.record_identifier.value.type = ck.Identifier.RECORD
    if zone_in_id is not None:
        rec.record_identifier.zone_identifier.value.name = zone_in_id
    if record_type is not None:
        rec.type.name = record_type
    for fname, value in fields:
        f = rec.record_field.add()
        if fname is not None:
            f.identifier.name = fname
        f.value.CopyFrom(value)
    if protection is not None:
        rec.protection_info.protection_info = protection
        rec.protection_info.protection_info_tag = tag or f"tag-{name}"
    elif tag:
        rec.protection_info.protection_info_tag = tag
    if pcs_key:
        rec.pcs_key = pcs_key
    return rec


def enc_value(value_type: int, plaintext: bytes, master: bytes, record_name: str, field_name: str, iv_label: str, zone=BEACON_STORE_ZONE) -> ck.Record.Value:
    data = pcs.encrypt_field(plaintext, holder(master), pcs.FieldContext(zone, record_name, field_name), iv=seed("iv:" + iv_label, 12))
    return ck.Record.Value(type=value_type, bytes_value=data, is_encrypted=True)


def value_json(v) -> dict:
    if v is None:
        return {"none": True}
    if isinstance(v, bool):
        return {"bool": v}
    if isinstance(v, bytes):
        return {"bytes": v.hex()}
    if isinstance(v, str):
        return {"str": v}
    if isinstance(v, int):
        return {"int": v}
    if isinstance(v, float):
        return {"double": v}
    if isinstance(v, datetime):
        delta = v - datetime(1970, 1, 1, tzinfo=timezone.utc)
        return {"date_micros": (delta.days * 86400 + delta.seconds) * 1_000_000 + delta.microseconds}
    if isinstance(v, ck.EncryptedValue):
        return {"wrapper": v.SerializeToString().hex()}
    raise TypeError(type(v))


def decrypted_json(r: beacons.DecryptedRecord) -> dict:
    return {"name": r.name, "record_type": r.record_type, "values": {k: value_json(v) for k, v in r.values.items()},
            "raw_values": {k: v.hex() for k, v in r.raw_values.items()}, "undecryptable": sorted(r.undecryptable)}


def accessory_json(a) -> dict:
    def micros(d):
        if d is None:
            return None
        delta = d - datetime(1970, 1, 1, tzinfo=timezone.utc)
        return (delta.days * 86400 + delta.seconds) * 1_000_000 + delta.microseconds
    return {
        "master_key": a.master_key.hex(), "skn": a.skn.hex(), "sks": a.sks.hex(), "paired_at": micros(a.paired_at),
        "name": a.name, "model": a.model, "identifier": a.identifier, "group_identifier": a._group_identifier,  # noqa: SLF001
        "serial_number": a.serial_number, "alignment_date_given": micros(a._alignment_date),  # noqa: SLF001
        "alignment_index_given": a._alignment_index,  # noqa: SLF001
    }


def gen_records_and_beacons(zone_objects) -> None:
    service, zone_master, zone_identity, zone_prot, defaults_prot, zone_keys, defaults = zone_objects
    # A record's protection names the zone identity key (the [observed] shape: zone meta identities).
    zone_holder = zone_identity

    def record_protection(master: bytes, label: str, *, recipient=zone_holder, version: int = 5) -> bytes:
        public = bare_x(recipient)
        return build_protection(entries=[(public, wrap_master_key(recipient.public_key(), master, "rec:" + label), None)],
                                truncated_key_id=pcs.compute_key_id(master)[:4], version=version, hmac_master_key=master,
                                meta=encrypt_meta(master, seq(ctx(1, octet(b"r"))), "rec-meta:" + label))

    paired_seconds = (datetime(2024, 3, 1, 12, 0, tzinfo=timezone.utc) - APPLE_EPOCH).total_seconds()
    paired_unix = (datetime(2023, 7, 4, 8, 30, 15, 500000, tzinfo=timezone.utc) - datetime(1970, 1, 1, tzinfo=timezone.utc)).total_seconds()
    observed_seconds = (datetime(2025, 1, 2, 3, 4, 5, tzinfo=timezone.utc) - APPLE_EPOCH).total_seconds()

    recs: list[ck.Record] = []

    def beacon(name: str, *, private=True, secondary="sharedSecret2", model: str | None = "AirTag1,1", stable: str | None = None,
               paired: float = paired_seconds, group: str | None = None, label: str | None = None, extra=None, master=None) -> None:
        label = label or name
        master = master or seed("rec-mk:" + label, 16)
        fields = []
        if private:
            fields.append(("privateKey", enc_value(20, seed("pk:" + label, 85), master, name, "privateKey", label + ":pk")))
        fields.append(("sharedSecret", enc_value(20, seed("skn:" + label, 32), master, name, "sharedSecret", label + ":skn")))
        if secondary:
            fields.append((secondary, enc_value(20, seed("sks:" + label, 32), master, name, secondary, label + ":sks")))
        fields.append(("pairingDate", enc_value(2, ev(date_value=ck.Date(time=paired)), master, name, "pairingDate", label + ":date")))
        if model is not None:
            fields.append(("model", enc_value(3, ev(string_value=model), master, name, "model", label + ":model")))
        if stable is not None:
            fields.append(("stableIdentifier", enc_value(3, ev(string_value=stable), master, name, "stableIdentifier", label + ":stable")))
        if group is not None:
            fields.append(("groupIdentifier", enc_value(3, ev(string_value=group), master, name, "groupIdentifier", label + ":group")))
        fields.append(("batteryLevel", enc_value(7, ev(signed_value=3), master, name, "batteryLevel", label + ":battery")))
        fields.append(("isZeus", ck.Record.Value(type=7, signed_value=1)))  # an unencrypted field: Python keeps its bytes_value (None)
        for f in extra or []:
            fields.append(f(master, name, label))
        recs.append(make_record(name, "MasterBeaconRecord", fields, protection=record_protection(master, label)))

    def naming(name: str, beacon_id: str, title: str | None, emoji: str | None = None) -> None:
        master = seed("rec-mk:" + name, 16)
        fields = [("associatedBeacon", enc_value(3, ev(string_value=beacon_id), master, name, "associatedBeacon", name + ":ab"))]
        if title is not None:
            fields.append(("name", enc_value(3, ev(string_value=title), master, name, "name", name + ":name")))
        if emoji is not None:
            fields.append(("emoji", enc_value(3, ev(string_value=emoji), master, name, "emoji", name + ":emoji")))
        fields.append(("roleId", enc_value(7, ev(signed_value=-5), master, name, "roleId", name + ":role")))
        recs.append(make_record(name, "BeaconNamingRecord", fields, protection=record_protection(master, name)))

    def alignment(name: str, beacon_id: str, index: int | None, observed: float | None, *, index_bytes=False) -> None:
        master = seed("rec-mk:" + name, 16)
        fields = [("beaconIdentifier", enc_value(3, ev(string_value=beacon_id), master, name, "beaconIdentifier", name + ":bi"))]
        if index is not None:
            if index_bytes:
                fields.append(("lastIndexObserved", enc_value(20, b"bad", master, name, "lastIndexObserved", name + ":idx")))
            else:
                fields.append(("lastIndexObserved", enc_value(7, ev(signed_value=index), master, name, "lastIndexObserved", name + ":idx")))
        if observed is not None:
            fields.append(("lastIndexObservationDate", enc_value(2, ev(date_value=ck.Date(time=observed)), master, name,
                                                                 "lastIndexObservationDate", name + ":obs")))
        recs.append(make_record(name, "KeyAlignmentRecord", fields, protection=record_protection(master, name)))

    # 1. An AirTag with a name, an alignment record, a serial in its stable identifier.
    beacon("BEACON-1", stable="2006~#hw~#SERIAL001", group="GROUP-1",
           extra=[lambda m, n, l: ("doubleField", enc_value(8, ev(date_value=ck.Date(time=1.5)), m, n, "doubleField", l + ":dbl")),
                  lambda m, n, l: ("doubleInt", enc_value(8, ev(signed_value=42), m, n, "doubleInt", l + ":dbl2")),
                  lambda m, n, l: ("listField", enc_value(15, ev(string_value="opaque"), m, n, "listField", l + ":list")),
                  lambda m, n, l: ("bytesField", enc_value(1, b"\x00\x01raw", m, n, "bytesField", l + ":bytes")),
                  lambda m, n, l: ("plainBytes", ck.Record.Value(type=1, bytes_value=b"plain")),
                  lambda m, n, l: ("brokenString", enc_value(3, ev(signed_value=1), m, n, "brokenString", l + ":broken")),
                  lambda m, n, l: ("notAWrapper", enc_value(3, b"\xff\xff\xff", m, n, "notAWrapper", l + ":nw")),
                  lambda m, n, l: ("wrongContext", enc_value(3, ev(string_value="x"), m, n, "someOtherField", l + ":wc")),
                  lambda m, n, l: ("encryptedNoBytes", ck.Record.Value(type=3, is_encrypted=True))])
    naming("NAMING-1", "BEACON-1", "Backpack", emoji="🎒")
    alignment("ALIGN-1", "BEACON-1", 19200, observed_seconds)
    # 2. A third-party accessory paired under the Unix epoch reading, no naming record, alignment unreadable.
    beacon("BEACON-2", model="", stable="a:/1234-5678~#SER-2", paired=paired_unix, secondary="secureLocationsSharedSecret")
    alignment("ALIGN-2", "BEACON-2", 5, None, index_bytes=True)
    # 3. AirPods-style stable identifier.
    beacon("BEACON-3", stable="a:/uuid~#\u00b6Model\u00a7hw\u00a7" + b"PODSER".hex() + "\u00a71", model=None)
    naming("NAMING-3", "BEACON-3", None)
    # 4. A device (no private key): grouped, but not locatable.
    beacon("BEACON-IPAD", private=False, model="iPad13,18", secondary="secureLocationsSharedSecret")
    # 5. Locatable but broken: no secondary secret, and one with an implausible pairing date.
    beacon("BEACON-NOSKS", secondary=None)
    beacon("BEACON-BADDATE", paired=0.0)
    # 6. Records decrypt_records does not want, or cannot open.
    recs.append(make_record("SAFE-1", "SafeLocation", [("latitude", ck.Record.Value(type=8, double_value=1.0))], protection=b"\x00"))
    recs.append(make_record("DEVKEY-1", "OwnedDeviceKeyRecord", [], protection=b"\x00"))
    recs.append(make_record("UNTYPED-1", None, [], protection=b"\x00"))
    recs.append(make_record("UNTYPED-2", "", [], protection=b"\x00"))
    other_master = seed("rec-mk:someone-else", 16)
    recs.append(make_record("BEACON-OTHER", "MasterBeaconRecord",
                            [("privateKey", enc_value(20, b"x" * 32, other_master, "BEACON-OTHER", "privateKey", "other"))],
                            protection=record_protection(other_master, "other", recipient=p256("someone-elses-zone"))))
    bad_kid = build_protection(entries=[(bare_x(zone_holder), wrap_master_key(zone_holder.public_key(), seed("k", 16), "badkid"), None)],
                               truncated_key_id=b"\xde\xad\xbe\xef", version=5)
    recs.append(make_record("BEACON-BADKID", "MasterBeaconRecord", [], protection=bad_kid))
    # 7. The zone-default branch: no protection on the record, a pcsKey naming one of the defaults (and one naming none).
    dmaster = defaults[1]
    recs.append(make_record("NAMING-DEFAULT", "BeaconNamingRecord",
                            [("associatedBeacon", enc_value(3, ev(string_value="BEACON-2"), dmaster, "NAMING-DEFAULT", "associatedBeacon", "nd")),
                             ("name", enc_value(3, ev(string_value="Keys"), dmaster, "NAMING-DEFAULT", "name", "nd2"))],
                            protection=None, pcs_key=pcs.compute_key_id(dmaster)[:4], tag="tag-no-structure"))
    recs.append(make_record("NAMING-NOMATCH", "BeaconNamingRecord", [], protection=None, pcs_key=b"\x00\x01"))
    # 8. Duplicate join keys: a second naming record for BEACON-1 (the last one wins).
    naming("NAMING-1B", "BEACON-1", "Backpack (renamed)")

    # Changes, as a record/sync page carries them: one deletion (no record), one whose type is only on the change.
    changes = [ck.RecordChange(record=r) for r in recs]
    deletion = ck.RecordChange(etag="deleted")
    deletion.identifier.value.name = "GONE-1"
    changes.insert(3, deletion)
    typed_on_change = make_record("TYPED-ON-CHANGE", None, [("f", ck.Record.Value(type=1, bytes_value=b"v"))], protection=None,
                                  zone_in_id="ZoneFromRecord")
    ch = ck.RecordChange(record=typed_on_change)
    ch.record_type.name = "LeashRecord"
    changes.append(ch)
    nameless = make_record("NAMELESS-FIELD", "LeashRecord", [(None, ck.Record.Value(type=1, bytes_value=b"v")),
                                                             ("dup", ck.Record.Value(type=1, bytes_value=b"first")),
                                                             ("other", ck.Record.Value(type=3, string_value="s")),
                                                             ("dup", ck.Record.Value(type=1, bytes_value=b"second"))], protection=b"", tag="t")
    changes.append(ck.RecordChange(record=nameless))

    cloud_records = records.records_from_changes(changes, BEACON_STORE_ZONE)
    no_zone = records.records_from_changes([ch], "")

    def record_json(r: records.CloudKitRecord) -> dict:
        return {"name": r.name, "zone_name": r.zone_name, "record_type": r.record_type, "etag": r.etag,
                "protection_info": r.protection_info.hex() if r.protection_info is not None else None,
                "protection_info_tag": r.protection_info_tag, "pcs_key": r.pcs_key.hex(),
                "fields": [{"name": f.name, "value_type": f.value_type, "is_encrypted": f.is_encrypted,
                            "raw": f.raw.hex() if f.raw is not None else None} for f in r.fields.values()]}

    dump("records.json", {
        "changes": [c.SerializeToString().hex() for c in changes],
        "records": [record_json(r) for r in cloud_records],
        "no_zone_records": [record_json(r) for r in no_zone],
        "wire_fields": [
            {"data": d.hex(), "fields": [[n, w, p.hex()] for n, w, p in records.iter_wire_fields(d)]}
            for d in (changes[0].SerializeToString()[:40], b"\x08\x96\x01\x12\x03abc\x1d\x01\x02\x03\x04\x21" + bytes(8) + b"\x2a\x05ab",
                      b"\x0b\x0c", b"\x12\x80", b"")
        ],
    })

    # decrypt_records over the whole zone (the zone keys come from the zone structure, as the store does)
    decrypted = beacons.decrypt_records(cloud_records, zone_keys, default_master_keys=defaults)
    groups = beacons.group_records(decrypted)
    accessories = beacons.accessories_from_records(decrypted)

    # Records the Python cannot classify (its DerError escapes decrypt_records): recorded separately.
    broken = make_record("BEACON-NOTDER", "MasterBeaconRecord", [], protection=b"\x61\x05\x30")
    broken_error = error_name(lambda: beacons.decrypt_records(records.records_from_changes([ck.RecordChange(record=broken)], BEACON_STORE_ZONE), zone_keys))

    dump("beacons.json", {
        "zone": {"service_keys": [key_json(service)], "zone_protection": zone_prot.hex(), "record_protection": defaults_prot.hex()},
        "zone_keys": [key_json(k) for k in zone_keys],
        "default_master_keys": [k.hex() for k in defaults],
        "changes": [c.SerializeToString().hex() for c in changes],
        "decrypted": [decrypted_json(r) for r in decrypted],
        "skipped": decrypted.skipped,
        "first_miss_present": decrypted.first_miss is not None,
        "groups": [{"beacon": g.beacon.name, "naming": g.naming.name if g.naming else None,
                    "alignment": g.alignment.name if g.alignment else None,
                    "can_be_located": beacons.can_be_located(g.beacon)} for g in groups],
        "accessories": [accessory_json(a) for a in accessories],
        "broken_record": {"change": ck.RecordChange(record=broken).SerializeToString().hex(), "python_error": broken_error},
        "serials": {s: beacons._extract_serial_from_stable_id([s]) for s in [  # noqa: SLF001
            "2006~#hw~#SERIAL001", "a:/1234~#SER-2", "noseparator", "a~#\u00b6M\u00a7h\u00a7" + b"AB".hex(), "a~#\u00b6M\u00a7h",
            "a~#\u00b6M\u00a7h\u00a7zz", "a~#\u00b6M\u00a7h\u00a74 1 4 2", "a~#\u00b6M\u00a7h\u00a7ff", "x~#", "~#"]},
        "dates": dates_vector(),
    })


def dates_vector() -> list:
    out = []
    for seconds in [0.0, 600_000_000.0, 600_000_000.5, 600_000_000.123456, 1_700_000_000.0, 1_700_000_000.25, 3.0e9, -1.0, 1e300,
                    float("nan")]:
        try:
            d = beacons._as_datetime(seconds)  # noqa: SLF001
            out.append({"seconds": repr(seconds), "result": value_json(d)})
        except Exception as e:  # noqa: BLE001
            out.append({"seconds": repr(seconds), "error": type(e).__name__})
    return out


# ------------------------------------------------------------------------------------------------- client.json


class _FakeResponse:
    def __init__(self, status: int, content: bytes) -> None:
        self.status_code = status
        self.content = content

    @property
    def ok(self) -> bool:
        return 200 <= self.status_code < 300

    def text(self) -> str:
        return self.content.decode()

    def json(self):
        return json.loads(self.content)


class _FakeHttp:
    def __init__(self, replies) -> None:
        self.replies = list(replies)
        self.seen: list[dict] = []

    async def post(self, url, *, headers=None, data=None, auth=None):
        self.seen.append({"url": url, "headers": dict(headers or {}), "body": gzip.decompress(data).hex() if data else "",
                          "auth": list(auth) if auth else None})
        return self.replies.pop(0)

    async def close(self) -> None:
        return


class _FakeAccount:
    dsid = "1234567890"
    device_uuid = "0f1e2d3c-4b5a-6978-8796-a5b4c3d2e1f0"
    client_info = "<MacBookPro18,3> <Mac OS X;13.4.1;22F82> <com.apple.AuthKit/1 (com.apple.dt.Xcode/3594.4.19)>"
    serial = "C02SYNTHETIC"
    timeout = 10
    service_tokens = {"mmeAuthToken": "SYNTHETIC-MME-TOKEN", "cloudKitToken": "SYNTHETIC-CK-TOKEN"}

    async def get_anisette_headers(self):
        return {"X-Apple-I-MD": "otp-synthetic", "X-Apple-I-MD-M": "machine-synthetic", "X-Mme-Device-Id": "DEVICE-SYNTHETIC"}


APP_INIT = {
    "cloudKitUserId": "_" + "0123456789abcdef" * 2,
    "cloudKitDatabaseUrl": "https://p42-ckdatabase.icloud.com:443",
    "cloudKitDatabaseGatewayUrl": "https://gateway.icloud.com/ckdatabase",
    "cloudKitShareUrl": "https://p42-ckshare.icloud.com:443",
    "cloudKitShareGatewayUrl": "https://gateway.icloud.com/ckshare",
    "cloudKitDeviceUrl": "https://p42-ckdevice.icloud.com:443",
    "cloudKitDeviceGatewayUrl": "https://gateway.icloud.com/ckdevice",
    "cloudKitCodeUrl": "https://p42-ckcode.icloud.com:443",
    "cloudKitCodeGatewayUrl": "https://gateway.icloud.com/ckcoderouter",
    "cloudKitMetricsUrl": "https://metrics.icloud.com",
    "values": [],
}


def frame(*messages: ck.ResponseOperation) -> bytes:
    out = b""
    for m in messages:
        out += client_mod.encode_delimited(m)  # same varint framing the server answers with
    return out


def gen_client() -> None:
    counter = {"op": 0, "uuid": 0}

    def op_id() -> str:
        counter["op"] += 1
        return f"{counter['op']:032X}"

    def req_uuid() -> str:
        counter["uuid"] += 1
        return f"00000000-0000-4000-8000-{counter['uuid']:012X}"

    client_mod._random_operation_id = op_id  # noqa: SLF001
    client_mod._random_request_uuid = req_uuid  # noqa: SLF001

    zone_reply = ck.ResponseOperation(result=ck.Result(code=1))
    z = zone_reply.zone_retrieve_response.zone_summary.add()
    z.target_zone.zone_identifier.value.name = "BeaconStore"
    z.target_zone.protection_info.protection_info = b"\x61\x00"
    z.target_zone.protection_info.protection_info_tag = "zone-tag"
    z.device_count = 10
    z2 = zone_reply.zone_retrieve_response.zone_summary.add()
    z2.target_zone.zone_identifier.value.name = "_defaultZone"

    page1 = ck.ResponseOperation(result=ck.Result(code=1))
    page1.retrieve_changes_response.record_change.add().etag = "e1"
    page1.retrieve_changes_response.sync_continuation_token = b"token-1"
    page1.retrieve_changes_response.status = 1
    page1.retrieve_changes_response.zone_attributes_changes = b"\x0a\x02hi"
    page2 = ck.ResponseOperation(result=ck.Result(code=2))
    page2.retrieve_changes_response.record_change.add().etag = "e2"
    page2.retrieve_changes_response.sync_continuation_token = b"token-2"
    page2.retrieve_changes_response.status = 3

    invoke_reply = ck.ResponseOperation(result=ck.Result(code=1))
    invoke_reply.function_invoke_response.serialized_result = b"\x0a\x03inner"

    replies = [
        _FakeResponse(200, json.dumps(APP_INIT).encode()),
        _FakeResponse(200, frame(zone_reply)),
        _FakeResponse(200, frame(page1)),
        _FakeResponse(200, frame(page2, page1)),
        _FakeResponse(200, frame(invoke_reply)),
    ]

    async def run() -> dict:
        client = client_mod.AsyncCloudKitClient(_FakeAccount())  # pyright: ignore [reportArgumentType]
        client._http = _FakeHttp(replies)  # noqa: SLF001
        zones = await client.zone_retrieve()
        changes = [c async for c in client.iter_records(BEACON_STORE_ZONE)]
        result = await client.function_invoke("Cuttlefish", "fetchViableBottles", b"\x0a\x01p")
        info = client.container_info
        return {
            "requests": client._http.seen,  # noqa: SLF001
            "zones": [zs.SerializeToString().hex() for zs in zones],
            "changes": [c.SerializeToString().hex() for c in changes],
            "invoke_result": result.hex(),
            "container": {"user_id": info.user_id, "partition": info.partition, "database_gateway_url": info.database_gateway_url,
                          "code_gateway_url": info.code_gateway_url},
            "replies": {"app_init": json.dumps(APP_INIT), "zone": frame(zone_reply).hex(), "page1": frame(page1).hex(),
                        "page2": frame(page2, page1).hex(), "invoke": frame(invoke_reply).hex()},
        }

    flow = asyncio.run(run())

    # A sync page that asks for a resume token and a page size.
    counter.update(op=100, uuid=100)
    single = [_FakeResponse(200, json.dumps(APP_INIT).encode()), _FakeResponse(200, frame(page2))]

    async def one_page() -> dict:
        client = client_mod.AsyncCloudKitClient(_FakeAccount())  # pyright: ignore [reportArgumentType]
        client._http = _FakeHttp(single)  # noqa: SLF001
        page = await client.record_sync(BEACON_STORE_ZONE, continuation_token=b"resume", max_changes=50)
        return {"requests": client._http.seen, "token": page.continuation_token.hex(), "status": page.status,  # noqa: SLF001
                "complete": page.complete}

    resumed = asyncio.run(one_page())

    identities = {}
    for s in ["<MacBookPro18,3> <Mac OS X;13.4.1;22F82> <com.apple.AuthKit/1 (com.apple.dt.Xcode/3594.4.19)>",
              "<iPhone13,2> <iPhone OS;14.4;18D52> <com.apple.akd/1.0 (com.apple.akd/1.0)>", "<Mac>", "garbage", "",
              "<A> <B> <C> <D>", "<MacBook> <macOS> <x>", "x<a>y<b;c;d>z"]:
        parsed = client_mod._ClientIdentity.parse(s)  # noqa: SLF001
        identities[s] = {"model": parsed.model, "os_version": parsed.os_version, "prefix": parsed.prefix,
                         "cloudkit_client_info": parsed.cloudkit_client_info}

    varints = {str(n): client_mod._encode_varint(n).hex() for n in (0, 1, 127, 128, 300, 16384, 2**31, 2**63)}  # noqa: SLF001
    delimited_errors = {}
    for name, data in {"truncated_varint": b"\x80", "truncated_body": b"\x05abc", "bad_message": b"\x02\xff\xff",
                       "empty": b""}.items():
        try:
            msgs = list(client_mod.decode_delimited(data))
            delimited_errors[name] = {"data": data.hex(), "count": len(msgs), "error": None}
        except Exception as e:  # noqa: BLE001
            delimited_errors[name] = {"data": data.hex(), "error": type(e).__name__}

    results = {}
    for name, result in {
        "success": ck.Result(code=1),
        "partial": ck.Result(code=2, error=ck.Error(error_description="half")),
        "throttled": ck.Result(code=3, error=ck.Error(client_error=ck.Error.ClientError(code=6), retry_after_seconds=30,
                                                     error_description="slow down", error_key="KEY12345")),
        "unknown_client": ck.Result(code=3, error=ck.Error(client_error=ck.Error.ClientError(code=99))),
        "server_only": ck.Result(code=4, error=ck.Error(server_error=ck.Error.ServerError(code=500))),
        "no_error": ck.Result(code=3),
    }.items():
        try:
            client_mod._check_result(result)  # noqa: SLF001
            results[name] = {"result": result.SerializeToString().hex(), "raises": False}
        except client_mod.CloudKitError as e:
            results[name] = {"result": result.SerializeToString().hex(), "raises": True, "message": str(e), "code": e.code,
                             "client_error": e.client_error, "server_error": e.server_error, "retry_after": e.retry_after,
                             "error_key": e.error_key}

    dump("client.json", {"flow": flow, "resumed": resumed, "identities": identities, "varints": varints,
                         "delimited": delimited_errors, "results": results,
                         "account": {k: getattr(_FakeAccount, k) for k in ("dsid", "device_uuid", "client_info", "serial")},
                         "anisette": asyncio.run(_FakeAccount().get_anisette_headers()),
                         "tokens": _FakeAccount.service_tokens})


def main() -> None:
    gen_der()
    pcs_out = gen_pcs()
    zone_objects = pcs_out.pop("_zone_objects")
    dump("pcs.json", pcs_out)
    gen_servicekeys()
    gen_records_and_beacons(zone_objects)
    gen_client()


if __name__ == "__main__":
    main()
